"use client";

import * as React from "react";
import { ChevronLeft, ChevronRight, Copy, Pencil } from "lucide-react";
import { NumberRoll } from "./number-roll";

/* ─────────────────────────────────────────────────────────
 * EDIT AND RESEND: change a sent message in place
 *
 *   sent      the message, with Copy and Edit on hover; Copy
 *             blurs into a check that draws itself
 *   editing   the bubble grows into an editor where it sits;
 *             Enter sends, Escape cancels
 *   versions  after a resend the pager slides open; "2 / 3"
 *             rolls, and the message slides in from the side
 *             you stepped toward while the bubble eases to fit
 *   disabled  editing waits while an answer is streaming
 *
 * The morph is one surface: it widens from its right edge and
 * grows to fit the field, its contents fade across, and it folds
 * back the same way.
 * ───────────────────────────────────────────────────────── */

export interface MessageEditProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onSubmit"
> {
  text: string;
  /** Called with the edited text; replace the message and regenerate from it. */
  onSubmit: (text: string) => void;
  /** Disable editing, e.g. while an answer streams. */
  disabled?: boolean;
  disabledReason?: string;
  /** Branches of this message, shown as "2 / 3". */
  versions?: {
    index: number;
    count: number;
    onIndexChange: (index: number) => void;
  };
  /** How the sent message renders; defaults to the text. */
  children?: React.ReactNode;
}

const EASE = "cubic-bezier(0.23,1,0.32,1)";
const MORPH = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const ICON = `cursor-pointer disabled:cursor-default flex size-7 items-center justify-center rounded-full text-muted-foreground transition-[background-color,color,transform] duration-150 hover:bg-accent hover:text-foreground active:scale-[0.94] disabled:pointer-events-none disabled:opacity-35 [&_svg]:size-3.5 ${FOCUS}`;

type Outgoing = {
  key: string;
  content: React.ReactNode;
  dir: number;
  width: number;
};

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Icons trade places through a blur: the old one shrinks away as the new one grows in. */
const swap = (on: boolean, reduced: boolean): React.CSSProperties => ({
  opacity: on ? 1 : 0,
  transform: on ? "none" : "scale(0.6)",
  filter: on ? "none" : "blur(3px)",
  transition: reduced
    ? "none"
    : `opacity 260ms ${MORPH}, transform 380ms ${MORPH}, filter 260ms ${MORPH}`,
});

function CopyGlyph({ copied, reduced }: { copied: boolean; reduced: boolean }) {
  return (
    <span className="relative flex size-3.5 items-center justify-center">
      <span
        className="absolute inset-0 flex items-center justify-center"
        style={swap(!copied, reduced)}
      >
        <Copy />
      </span>
      <span
        className="absolute inset-0 flex items-center justify-center text-foreground"
        style={swap(copied, reduced)}
      >
        <svg viewBox="0 0 16 16" fill="none">
          <path
            d="M3.5 8.5 6.5 11.5 12.5 4.5"
            stroke="currentColor"
            strokeWidth="1.8"
            strokeLinecap="round"
            strokeLinejoin="round"
            pathLength={1}
            strokeDasharray={1}
            style={{
              strokeDashoffset: copied ? 0 : 1,
              transition:
                copied && !reduced
                  ? `stroke-dashoffset 380ms ${MORPH} 100ms`
                  : "none",
            }}
          />
        </svg>
      </span>
    </span>
  );
}

/** The message you stepped away from: it leaves toward the side you came from. */
function Leaving({
  item,
  onDone,
}: {
  item: Outgoing;
  onDone: (key: string) => void;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        {
          opacity: 0,
          filter: "blur(6px)",
          transform: `translateX(${-item.dir * 16}px)`,
        },
      ],
      { duration: 240, easing: MORPH, fill: "forwards" },
    );
    animation.onfinish = () => onDone(item.key);
    return () => animation.cancel();
  }, [item, onDone]);
  return (
    <div
      ref={ref}
      aria-hidden="true"
      inert
      className="pointer-events-none absolute right-0 top-0 whitespace-pre-wrap px-4 py-2.5 text-[14px] leading-relaxed text-foreground"
      style={{ width: item.width }}
    >
      {item.content}
    </div>
  );
}

export function MessageEdit({
  text,
  onSubmit,
  disabled = false,
  disabledReason = "Wait for the answer to finish",
  versions,
  children,
  className = "",
  ...props
}: MessageEditProps) {
  const reduced = useReducedMotion();
  const [editing, setEditing] = React.useState(false);
  const [draft, setDraft] = React.useState(text);
  const [copied, setCopied] = React.useState(false);
  const surfaceRef = React.useRef<HTMLDivElement>(null);
  const fieldRef = React.useRef<HTMLTextAreaElement>(null);
  const editRef = React.useRef<HTMLButtonElement>(null);
  const fromRef = React.useRef<DOMRect | null>(null);
  const returnFocus = React.useRef(false);
  const contentRef = React.useRef<HTMLDivElement>(null);
  const versionFrom = React.useRef<DOMRect | null>(null);

  // Stepping between versions: remember what was showing, so it can leave while the new one arrives.
  const content = children ?? text;
  const index = versions?.index ?? 0;
  const [shown, setShown] = React.useState({
    text,
    index,
    content,
    editing,
    step: 0,
  });
  const [outgoing, setOutgoing] = React.useState<Outgoing[]>([]);
  const [enterDir, setEnterDir] = React.useState(0);
  if (shown.text !== text || shown.editing !== editing) {
    // A resend lands while the editor folds back, which is motion enough; only a step between versions slides.
    const stepped =
      shown.text !== text && !editing && !shown.editing && !reduced;
    const dir = Math.sign(index - shown.index) || 1;
    setShown({ text, index, content, editing, step: shown.step + 1 });
    setEnterDir(stepped ? dir : 0);
    if (stepped) {
      // Capture the live layout before React replaces the text. Cached dimensions
      // can predate a font load, and integer offsetWidth can wrap the final word.
      versionFrom.current = surfaceRef.current?.getBoundingClientRect() ?? null;
      setOutgoing((o) => [
        ...o,
        {
          key: `${shown.step}`,
          content: shown.content,
          dir,
          width: contentRef.current?.getBoundingClientRect().width ?? 0,
        },
      ]);
    }
  }
  const doneLeaving = React.useCallback(
    (key: string) => setOutgoing((o) => o.filter((x) => x.key !== key)),
    [],
  );

  const morph = (next: boolean) => {
    fromRef.current = surfaceRef.current?.getBoundingClientRect() ?? null;
    setEditing(next);
  };

  const start = () => {
    if (disabled) return;
    setDraft(text);
    morph(true);
  };

  const cancel = (refocus = true) => {
    returnFocus.current = refocus;
    morph(false);
  };

  const send = () => {
    const next = draft.trim();
    if (!next || next === text.trim()) return;
    onSubmit(next);
    returnFocus.current = true;
    morph(false);
  };

  // Animate the surface from where it was to where it lands (both directions).
  React.useLayoutEffect(() => {
    const el = surfaceRef.current;
    const from = fromRef.current;
    fromRef.current = null;
    if (editing) {
      const field = fieldRef.current;
      if (field) {
        field.style.height = "auto";
        field.style.height = `${field.scrollHeight}px`;
        field.focus({ preventScroll: true });
        field.setSelectionRange(field.value.length, field.value.length);
      }
    } else if (returnFocus.current) {
      returnFocus.current = false;
      editRef.current?.focus({ preventScroll: true });
    }
    if (!el || !from || reduced) return;
    const to = el.getBoundingClientRect();
    const animation = el.animate(
      [
        { width: `${from.width}px`, height: `${from.height}px` },
        { width: `${to.width}px`, height: `${to.height}px` },
      ],
      { duration: 380, easing: EASE },
    );
    return () => animation.cancel();
  }, [editing, reduced]);

  // A new version: the bubble eases from its old size to the new text, which slides in from the side you stepped toward.
  React.useLayoutEffect(() => {
    const el = surfaceRef.current;
    const pane = contentRef.current;
    const from = versionFrom.current;
    versionFrom.current = null;
    if (reduced || !enterDir || !el || !pane || !from) return;
    const to = el.getBoundingClientRect();
    // Let the surface resize without reflowing the words inside it. Anchor the
    // text at the right edge, including while the surface is narrower than it.
    pane.style.width = `${to.width}px`;
    pane.style.marginLeft = `calc(100% - ${to.width}px)`;
    const releaseWidth = () => {
      pane.style.width = "";
      pane.style.marginLeft = "";
    };
    const resize = el.animate(
      [
        { width: `${from.width}px`, height: `${from.height}px` },
        { width: `${to.width}px`, height: `${to.height}px` },
      ],
      { duration: 420, easing: MORPH },
    );
    resize.onfinish = releaseWidth;
    const entrance = pane.animate(
      [
        {
          opacity: 0,
          filter: "blur(6px)",
          transform: `translateX(${enterDir * 16}px)`,
        },
        { opacity: 1, filter: "blur(0px)", transform: "none" },
      ],
      { duration: 420, easing: MORPH, delay: 60, fill: "backwards" },
    );
    return () => {
      resize.cancel();
      entrance.cancel();
      releaseWidth();
    };
  }, [text, enterDir, reduced]);

  React.useLayoutEffect(() => {
    if (reduced) setOutgoing([]);
  }, [reduced]);

  React.useEffect(() => {
    if (!copied) return;
    const timer = window.setTimeout(() => setCopied(false), 1600);
    return () => window.clearTimeout(timer);
  }, [copied]);

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(text);
      setCopied(true);
    } catch {
      // Clipboard blocked; nothing to show.
    }
  };

  const unchanged = draft.trim() === text.trim() || !draft.trim();

  return (
    <div
      className={`group/message flex w-full flex-col items-end ${className}`}
      {...props}
    >
      <div
        ref={surfaceRef}
        className={`overflow-hidden rounded-[14px] transition-[background-color,box-shadow] duration-300 ${
          editing
            ? "w-full bg-background shadow-[0_0_0_1px_var(--border)]"
            : "w-fit max-w-[85%] bg-muted shadow-[0_0_0_1px_transparent]"
        }`}
      >
        {editing ? (
          <div
            key="editor"
            className="p-3 animate-[ui-fade-in_220ms_ease-out_100ms_both] motion-reduce:animate-none"
          >
            <textarea
              ref={fieldRef}
              value={draft}
              rows={1}
              aria-label="Edit message"
              onChange={(e) => {
                setDraft(e.target.value);
                e.target.style.height = "auto";
                e.target.style.height = `${e.target.scrollHeight}px`;
              }}
              onKeyDown={(e) => {
                if (e.nativeEvent.isComposing) return;
                if (e.key === "Escape") {
                  e.preventDefault();
                  cancel();
                } else if (e.key === "Enter" && !e.shiftKey) {
                  e.preventDefault();
                  send();
                }
              }}
              className="block max-h-60 w-full resize-none bg-transparent px-1 text-[14px] leading-relaxed text-foreground outline-none"
            />
            <div className="mt-2 flex items-center justify-end gap-1">
              <button
                type="button"
                onClick={() => cancel()}
                className={`cursor-pointer h-8 rounded-full px-3 text-[12.5px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
              >
                Cancel
              </button>
              <button
                type="button"
                onClick={send}
                disabled={unchanged}
                className={`cursor-pointer disabled:cursor-default h-8 rounded-full bg-primary px-3.5 text-[12.5px] font-medium text-primary-foreground transition-[opacity,transform] duration-150 active:scale-[0.96] disabled:opacity-35 ${FOCUS}`}
              >
                Send
              </button>
            </div>
          </div>
        ) : (
          <div
            key="message"
            className="relative animate-[ui-fade-in_220ms_ease-out_100ms_both] motion-reduce:animate-none"
          >
            {outgoing.map((o) => (
              <Leaving key={o.key} item={o} onDone={doneLeaving} />
            ))}
            <div
              key={text}
              ref={contentRef}
              className="whitespace-pre-wrap px-4 py-2.5 text-[14px] leading-relaxed text-foreground"
            >
              {content}
            </div>
          </div>
        )}
      </div>

      <div
        inert={editing}
        className={`mt-1 flex items-center gap-0.5 transition-opacity duration-200 ${
          editing
            ? "opacity-0"
            : "opacity-0 focus-within:opacity-100 group-hover/message:opacity-100 [@media(hover:none)]:opacity-100"
        }`}
      >
        {versions && (
          // Slides open the first time there is a second version.
          <span
            inert={versions.count < 2}
            className="grid"
            style={{
              gridTemplateColumns: versions.count > 1 ? "1fr" : "0fr",
              opacity: versions.count > 1 ? 1 : 0,
              transition: reduced
                ? "none"
                : `grid-template-columns 420ms ${MORPH}, opacity 300ms ${MORPH}`,
            }}
          >
            <span className="flex min-w-0 items-center overflow-hidden">
              <span className="mr-1 flex shrink-0 items-center">
                <button
                  type="button"
                  aria-label="Previous version"
                  disabled={versions.index <= 0}
                  onClick={() => versions.onIndexChange(versions.index - 1)}
                  className={ICON}
                >
                  <ChevronLeft />
                </button>
                <span
                  aria-live="polite"
                  className="flex min-w-[2.5rem] justify-center gap-[0.5ch] font-mono text-[11px] tabular-nums text-muted-foreground"
                >
                  <span className="sr-only">Version </span>
                  <NumberRoll value={versions.index + 1} duration={700} />
                  <span aria-hidden="true">/</span>
                  <span className="sr-only">of</span>
                  <NumberRoll value={versions.count} duration={700} />
                </span>
                <button
                  type="button"
                  aria-label="Next version"
                  disabled={versions.index >= versions.count - 1}
                  onClick={() => versions.onIndexChange(versions.index + 1)}
                  className={ICON}
                >
                  <ChevronRight />
                </button>
              </span>
            </span>
          </span>
        )}
        <button
          type="button"
          aria-label="Copy message"
          onClick={copy}
          className={ICON}
        >
          <CopyGlyph copied={copied} reduced={reduced} />
        </button>
        <button
          ref={editRef}
          type="button"
          aria-label="Edit message"
          title={disabled ? disabledReason : undefined}
          aria-disabled={disabled || undefined}
          onClick={start}
          className={`${ICON} aria-disabled:cursor-not-allowed aria-disabled:opacity-35 aria-disabled:hover:bg-transparent aria-disabled:hover:text-muted-foreground`}
        >
          <Pencil />
        </button>
      </div>
      {/* Outside the buttons, so their names stay their labels. */}
      <span role="status" className="sr-only">
        {copied ? "Copied" : ""}
      </span>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}
